import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.DXGyWiRo.js";const h=JSON.parse('{"title":"IDE Settings","description":"","frontmatter":{},"headers":[],"relativePath":"settings/ide-setting.md","filePath":"settings/ide-setting.md","lastUpdated":1786671054000}'),n={name:"settings/ide-setting.md"};function d(s,t,i,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ide-settings" tabindex="-1">IDE Settings <a class="header-anchor" href="#ide-settings" aria-label="Permalink to &quot;IDE Settings&quot;">​</a></h1><p>EasyYapi provides IDE-level settings that can be configured within IDEA.</p><h2 id="opening-settings" tabindex="-1">Opening Settings <a class="header-anchor" href="#opening-settings" aria-label="Permalink to &quot;Opening Settings&quot;">​</a></h2><p><kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd></p><h2 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>postman.url</td><td>Postman export URL</td></tr><tr><td>postman.token</td><td>Postman API Token</td></tr><tr><td>yapi.server</td><td>YApi server address</td></tr><tr><td>yapi.token</td><td>YApi project Token</td></tr><tr><td>project.name</td><td>Project name</td></tr></tbody></table><h2 id="export-settings" tabindex="-1">Export Settings <a class="header-anchor" href="#export-settings" aria-label="Permalink to &quot;Export Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>outputDemo</td><td>Generate response demo when exporting Markdown</td></tr><tr><td>outputCharset</td><td>Export character set</td></tr></tbody></table><h2 id="framework-toggles" tabindex="-1">Framework Toggles <a class="header-anchor" href="#framework-toggles" aria-label="Permalink to &quot;Framework Toggles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td>feignEnable</td><td>Enable Feign client support</td><td><code>false</code></td></tr><tr><td>jaxrsEnable</td><td>Enable JAX-RS support</td><td><code>true</code></td></tr><tr><td>actuatorEnable</td><td>Enable Spring Actuator support</td><td><code>false</code></td></tr><tr><td>grpcEnable</td><td>Enable gRPC support</td><td><code>true</code></td></tr><tr><td>swaggerEnable</td><td>Enable Swagger support</td><td><code>true</code></td></tr><tr><td>swagger3Enable</td><td>Enable Swagger 3 / OpenAPI support</td><td><code>true</code></td></tr></tbody></table><h2 id="recommended-config" tabindex="-1">Recommended Config <a class="header-anchor" href="#recommended-config" aria-label="Permalink to &quot;Recommended Config&quot;">​</a></h2><p>EasyYapi includes built-in recommended configuration that can be enabled in settings. The recommended config contains commonly used rules and type conversions.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>In EasyYapi 3.2, the <strong>Features</strong> tab is the single place to enable or disable extension points. Its lists are built dynamically from the installed plugin components:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it controls</th></tr></thead><tbody><tr><td><strong>API Features</strong></td><td>API Scanning (master switch, default on), with nested Automatic API Scanning (default on) and Concurrent API Scanning (default off), plus Editor Integration (gutter icons/line markers, default on, requires API Scanning).</td></tr><tr><td><strong>Framework Support</strong></td><td>Framework recognizers such as Feign, JAX-RS, Actuator, gRPC, and Custom.</td></tr><tr><td><strong>Export Channels</strong></td><td>YApi, Postman, Markdown, cURL, HttpClient, Hoppscotch (Beta), and OpenAPI (Beta). Experimental channels are disabled by default.</td></tr><tr><td><strong>Field Format Channels</strong></td><td>Field serializers such as JSON, JSON5, Properties, and YAML.</td></tr></tbody></table><p>Most framework recognizers, export channels, field-format channels, and extension configs can be enabled or disabled from Settings. API scanning, automatic/concurrent scanning, and editor integration are now controlled from the <strong>Features</strong> tab (API Features group). The <strong>API Scanning</strong> toggle in the Features tab is the master switch for API discovery. Features take effect immediately without restarting the IDE.</p><p>Manual rescan stays available even when Automatic API Scanning is turned off. Disabling API Scanning automatically disables Automatic API Scanning, Concurrent API Scanning, and Editor Integration.</p><h2 id="curl" tabindex="-1">cURL <a class="header-anchor" href="#curl" aria-label="Permalink to &quot;cURL&quot;">​</a></h2><p>The cURL settings tab controls variable rendering and the defaults used by both batch export and Dashboard <strong>Copy as cURL</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Render mode</strong></td><td>Keep placeholders, resolve with the active environment, or ask before each export. Environment values take precedence over config-reader values.</td></tr><tr><td><strong>Copy from edited</strong></td><td>Use the endpoint edited in the Dashboard instead of the source endpoint when copying cURL.</td></tr><tr><td><strong>Include comments and section dividers</strong></td><td>Add endpoint headings and separators to a batch script.</td></tr><tr><td><strong>Pretty-print JSON body</strong></td><td>Format JSON request bodies with indentation.</td></tr><tr><td><strong>Multi-line format</strong></td><td>Put one cURL flag on each line.</td></tr><tr><td><strong>Long flags</strong></td><td>Use <code>--request</code>, <code>--header</code>, <code>--data</code>, and <code>--form</code> instead of short flags.</td></tr><tr><td><strong>Response example</strong></td><td>Append an available response body as a comment.</td></tr><tr><td><strong>Run pre-request scripts</strong></td><td>Apply folder/class scripts during batch export and folder/class/endpoint scripts for single-endpoint copy.</td></tr></tbody></table><p>The export dialog exposes the formatting and pre-request-script options as per-export overrides.</p><h2 id="openapi-beta" tabindex="-1">OpenAPI (Beta) <a class="header-anchor" href="#openapi-beta" aria-label="Permalink to &quot;OpenAPI (Beta)&quot;">​</a></h2><p>OpenAPI export is disabled by default. After enabling it in <strong>Features</strong>, the OpenAPI settings tab lets you choose <strong>JSON</strong>, <strong>YAML</strong>, or <strong>Ask each export</strong>. The default file names are <code>openapi.json</code> and <code>openapi.yaml</code>.</p><p>Document-level metadata is configured with <code>openapi.info.title</code>, <code>openapi.info.version</code>, <code>openapi.info.description</code>, and <code>openapi.server.url</code> rules. The legacy <code>openapi.host</code> rule is also supported. See <a href="/guide/export-openapi">Export to OpenAPI</a>.</p><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h2><p>The Markdown settings tab is a persistent channel tab that controls the template used by Markdown export. These settings are reused across every export — the export dialog only asks for Output Directory and File Name.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Template File</strong></td><td>Path to a local template file (<code>.tpl</code> or <code>.md.tpl</code>).</td></tr><tr><td><strong>Template URL</strong></td><td>Remote <code>http(s)</code> URL serving a template. Responses are cached for 10 minutes; redirects are <strong>not</strong> followed.</td></tr><tr><td><strong>Language</strong></td><td>Combo box of bundled locale templates (e.g. <code>zh-CN</code>, <code>ja</code>, <code>en</code>). Selecting a bundled locale renders the document with that locale&#39;s template.</td></tr><tr><td><strong>Show inline template</strong></td><td>Toggles the inline template editor — a multi-line text area for entering template content directly.</td></tr><tr><td><strong>Copy default template</strong></td><td>Saves the bundled default template to a file so you can edit it as a starting point.</td></tr></tbody></table><p>See <a href="/guide/export2markdown">Export to Markdown</a> for the template resolution order and the <code>markdown.template*</code> config rules.</p><h2 id="custom-framework" tabindex="-1">Custom framework <a class="header-anchor" href="#custom-framework" aria-label="Permalink to &quot;Custom framework&quot;">​</a></h2><p>Custom framework support is disabled by default and is enabled from <strong>Features</strong> &gt; <strong>Framework Support</strong>. Its dedicated settings provide an optional line-marker toggle. Extraction itself is configured with <code>custom.*</code> rules; see <a href="/framework/custom">Custom Framework</a>.</p>',30)])])}const u=e(n,[["render",d]]);export{h as __pageData,u as default};
